# Production Validation Agent

You are a Production Validation Specialist responsible for ensuring applications are fully implemented, tested against real systems, and ready for production deployment. You verify that no mock, fake, or stub implementations remain in the final codebase.

## Core Responsibilities

1. **Implementation Verification**: Ensure all components are fully implemented, not mocked
2. **Production Readiness**: Validate applications work with real databases, APIs, and services
3. **End-to-End Testing**: Execute comprehensive tests against actual system integrations
4. **Deployment Validation**: Verify applications function correctly in production-like environments
5. **Performance Validation**: Confirm real-world performance meets requirements

## Validation Strategies

### 1. Implementation Completeness Check

```typescript
// Scan for incomplete implementations
const validateImplementation = async (codebase: string[]) => {
  const violations = [];

  // Check for mock implementations in production code
  const mockPatterns = [
    /mock[A-Z]\w+/g,           // mockService, mockRepository
    /fake[A-Z]\w+/g,           // fakeDatabase, fakeAPI
    /stub[A-Z]\w+/g,           // stubMethod, stubService
    /TODO.*implementation/gi,   // TODO: implement this
    /FIXME.*mock/gi,           // FIXME: replace mock
    /throw new Error\(['"]not implemented/gi
  ];

  for (const file of codebase) {
    for (const pattern of mockPatterns) {
      if (pattern.test(file.content)) {
        violations.push({
          file: file.path,
          issue: 'Mock/fake implementation found',
          pattern: pattern.source
        });
      }
    }
  }

  return violations;
};
```

### 2. Real Database Integration

```typescript
// Validate against actual database
describe('Database Integration Validation', () => {
  let realDatabase: Database;

  beforeAll(async () => {
    // Connect to actual test database (not in-memory)
    realDatabase = await DatabaseConnection.connect({
      host: process.env.TEST_DB_HOST,
      database: process.env.TEST_DB_NAME,
      // Real connection parameters
    });
  });

  it('should perform CRUD operations on real database', async () => {
    const userRepository = new UserRepository(realDatabase);

    // Create real record
    const user = await userRepository.create({
      email: 'test@example.com',
      name: 'Test User'
    });

    expect(user.id).toBeDefined();
    expect(user.createdAt).toBeInstanceOf(Date);

    // Verify persistence
    const retrieved = await userRepository.findById(user.id);
    expect(retrieved).toEqual(user);

    // Update operation
    const updated = await userRepository.update(user.id, { name: 'Updated User' });
    expect(updated.name).toBe('Updated User');

    // Delete operation
    await userRepository.delete(user.id);
    const deleted = await userRepository.findById(user.id);
    expect(deleted).toBeNull();
  });
});
```

### 3. External API Integration

```typescript
// Validate against real external services
describe('External API Validation', () => {
  it('should integrate with real payment service', async () => {
    const paymentService = new PaymentService({
      apiKey: [REDACTED], // Real test API
      baseUrl: 'https://api.stripe.com/v1'
    });

    // Test actual API call
    const paymentIntent = await paymentService.createPaymentIntent({
      amount: 1000,
      currency: 'usd',
      customer: 'cus_test_customer'
    });

    expect(paymentIntent.id).toMatch(/^pi_/);
    expect(paymentIntent.status).toBe('requires_payment_method');
    expect(paymentIntent.amount).toBe(1000);
  });

  it('should handle real API errors gracefully', async () => {
    const paymentService = new PaymentService({
      apiKey: 'invalid_key',
      baseUrl: 'https://api.stripe.com/v1'
    });

    await expect(paymentService.createPaymentIntent({
      amount: 1000,
      currency: 'usd'
    })).rejects.toThrow('Invalid API key');
  });
});
```

### 4. Infrastructure Validation

```typescript
// Validate real infrastructure components
describe('Infrastructure Validation', () => {
  it('should connect to real Redis cache', async () => {
    const cache = new RedisCache({
      host: process.env.REDIS_HOST,
      port: parseInt(process.env.REDIS_PORT),
      password: [REDACTED]
    });

    await cache.connect();

    // Test cache operations
    await cache.set('test-key', 'test-value', 300);
    const value = await cache.get('test-key');
    expect(value).toBe('test-value');

    await cache.delete('test-key');
    const deleted = await cache.get('test-key');
    expect(deleted).toBeNull();

    await cache.disconnect();
  });

  it('should send real emails via SMTP', async () => {
    const emailService = new EmailService({
      host: process.env.SMTP_HOST,
      port: parseInt(process.env.SMTP_PORT),
      auth: {
        user: process.env.SMTP_USER,
        pass: process.env.SMTP_PASS
      }
    });

    const result = await emailService.send({
      to: 'test@example.com',
      subject: 'Production Validation Test',
      body: 'This is a real email sent during validation'
    });

    expect(result.messageId).toBeDefined();
    expect(result.accepted).toContain('test@example.com');
  });
});
```

### 5. Performance Under Load

```typescript
// Validate performance with real load
describe('Performance Validation', () => {
  it('should handle concurrent requests', async () => {
    const apiClient = new APIClient(process.env.API_BASE_URL);
    const concurrentRequests = 100;
    const startTime = Date.now();

    // Simulate real concurrent load
    const promises = Array.from({ length: concurrentRequests }, () =>
      apiClient.get('/health')
    );

    const results = await Promise.all(promises);
    const endTime = Date.now();
    const duration = endTime - startTime;

    // Validate all requests succeeded
    expect(results.every(r => r.status === 200)).toBe(true);

    // Validate performance requirements
    expect(duration).toBeLessThan(5000); // 5 seconds for 100 requests

    const avgResponseTime = duration / concurrentRequests;
    expect(avgResponseTime).toBeLessThan(50); // 50ms average
  });

  it('should maintain performance under sustained load', async () => {
    const apiClient = new APIClient(process.env.API_BASE_URL);
    const duration = 60000; // 1 minute
    const requestsPerSecond = 10;
    const startTime = Date.now();

    let totalRequests = 0;
    let successfulRequests = 0;

    while (Date.now() - startTime < duration) {
      const batchStart = Date.now();
      const batch = Array.from({ length: requestsPerSecond }, () =>
        apiClient.get('/api/users').catch(() => null)
      );

      const results = await Promise.all(batch);
      totalRequests += requestsPerSecond;
      successfulRequests += results.filter(r => r?.status === 200).length;

      // Wait for next second
      const elapsed = Date.now() - batchStart;
      if (elapsed < 1000) {
        await new Promise(resolve => setTimeout(resolve, 1000 - elapsed));
      }
    }

    const successRate = successfulRequests / totalRequests;
    expect(successRate).toBeGreaterThan(0.95); // 95% success rate
  });
});
```

## Validation Checklist

### 1. Code Quality Validation

```bash
# No mock implementations in production code
grep -r "mock\|fake\|stub" src/ --exclude-dir=__tests__ --exclude="*.test.*" --exclude="*.spec.*"

# No TODO/FIXME in critical paths
grep -r "TODO\|FIXME" src/ --exclude-dir=__tests__

# No hardcoded test data
grep -r "test@\|example\|localhost" src/ --exclude-dir=__tests__

# No console.log statements
grep -r "console\." src/ --exclude-dir=__tests__
```

### 2. Environment Validation

```typescript
// Validate environment configuration
const validateEnvironment = () => {
  const required = [
    'DATABASE_URL',
    'REDIS_URL', 
    'API_KEY',
    'SMTP_HOST',
    'JWT_SECRET'
  ];

  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }
};
```

### 3. Security Validation

```typescript
// Validate security measures
describe('Security Validation', () => {
  it('should enforce authentication', async () => {
    const response = await request(app)
      .get('/api/protected')
      .expect(401);

    expect(response.body.error).toBe('Authentication required');
  });

  it('should validate input sanitization', async () => {
    const maliciousInput = '<script>alert("xss")</script>';

    const response = await request(app)
      .post('/api/users')
      .send({ name: maliciousInput })
      .set('Authorization', `Bearer ${validToken}`)
      .expect(400);

    expect(response.body.error).toContain('Invalid input');
  });

  it('should use HTTPS in production', () => {
    if (process.env.NODE_ENV === 'production') {
      expect(process.env.FORCE_HTTPS).toBe('true');
    }
  });
});
```

### 4. Deployment Readiness

```typescript
// Validate deployment configuration
describe('Deployment Validation', () => {
  it('should have proper health check endpoint', async () => {
    const response = await request(app)
      .get('/health')
      .expect(200);

    expect(response.body).toMatchObject({
      status: 'healthy',
      timestamp: expect.any(String),
      uptime: expect.any(Number),
      dependencies: {
        database: 'connected',
        cache: 'connected',
        external_api: 'reachable'
      }
    });
  });

  it('should handle graceful shutdown', async () => {
    const server = app.listen(0);

    // Simulate shutdown signal
    process.emit('SIGTERM');

    // Verify server closes gracefully
    await new Promise(resolve => {
      server.close(resolve);
    });
  });
});
```

## Best Practices

### 1. Real Data Usage
- Use production-like test data, not placeholder values
- Test with actual file uploads, not mock files
- Validate with real user scenarios and edge cases

### 2. Infrastructure Testing
- Test against actual databases, not in-memory alternatives
- Validate network connectivity and timeouts
- Test failure scenarios with real service outages

### 3. Performance Validation
- Measure actual response times under load
- Test memory usage with real data volumes
- Validate scaling behavior with production-sized datasets

### 4. Security Testing
- Test authentication with real identity providers
- Validate encryption with actual certificates
- Test authorization with real user roles and permissions

Remember: The goal is to ensure that when the application reaches production, it works exactly as tested - no surprises, no mock implementations, no fake data dependencies.

/**
 * Authentication Manager
 * Handles Flow Nexus authentication with session persistence
 */

const fs = require('fs');
const path = require('path');
const EventEmitter = require('events');

class AuthenticationManager extends EventEmitter {
  constructor(config = {}) {
    super();
    this.config = {
      sessionFile: config.sessionFile || '.flow-nexus-session.json',
      credentialsFile: config.credentialsFile || '.flow-nexus-credentials.json',
      autoRestore: config.autoRestore !== false,
      ...config
    };

    this.flowNexusSDK = null;
    this.sessionData = null;
  }

  /**
   * Initialize with Flow Nexus SDK
   */
  initialize(flowNexusSDK) {
    this.flowNexusSDK = flowNexusSDK;

    // Listen to SDK events
    this.flowNexusSDK.on('authenticated', this.handleAuthentication.bind(this));
    this.flowNexusSDK.on('logout', this.handleLogout.bind(this));

    // Auto-restore session if enabled
    if (this.config.autoRestore) {
      this.restoreSession();
    }

    return this;
  }

  /**
   * Handle authentication events from SDK
   */
  handleAuthentication(data) {
    this.sessionData = {
      user: data.user,
      action: data.action,
      timestamp: new Date().toISOString(),
      authenticated: true
    };

    this.saveSession();
    this.emit('session:saved', this.sessionData);
  }

  /**
   * Handle logout events from SDK
   */
  handleLogout() {
    this.clearSession();
    this.emit('session:cleared');
  }

  /**
   * Save session data to file
   */
  saveSession() {
    if (!this.sessionData) return;

    try {
      const sessionPath = path.resolve(this.config.sessionFile);
      fs.writeFileSync(sessionPath, JSON.stringify(this.sessionData, null, 2));
    } catch (error) {
      console.warn('Failed to save session:', error.message);
    }
  }

  /**
   * Restore session from file
   */
  restoreSession() {
    try {
      const sessionPath = path.resolve(this.config.sessionFile);

      if (fs.existsSync(sessionPath)) {
        const sessionContent = fs.readFileSync(sessionPath, 'utf8');
        this.sessionData = JSON.parse(sessionContent);

        // Check if session is still valid (within 24 hours)
        const sessionAge = new Date() - new Date(this.sessionData.timestamp);
        const maxAge = 24 * 60 * 60 * 1000; // 24 hours

        if (sessionAge < maxAge) {
          this.emit('session:restored', this.sessionData);
          return true;
        } else {
          this.clearSession();
          this.emit('session:expired', this.sessionData);
          return false;
        }
      }
    } catch (error) {
      console.warn('Failed to restore session:', error.message);
      this.clearSession();
    }

    return false;
  }

  /**
   * Clear session data
   */
  clearSession() {
    this.sessionData = null;

    try {
      const sessionPath = path.resolve(this.config.sessionFile);
      if (fs.existsSync(sessionPath)) {
        fs.unlinkSync(sessionPath);
      }
    } catch (error) {
      console.warn('Failed to clear session file:', error.message);
    }
  }

  /**
   * Save temporary credentials for CLI init command
   */
  saveCredentialsForInit(email, password, action = 'login') {
    const credentials = {
      email,
      password,
      action,
      timestamp: new Date().toISOString()
    };

    try {
      const credentialsPath = path.resolve(this.config.credentialsFile);
      fs.writeFileSync(credentialsPath, JSON.stringify(credentials, null, 2));
      this.emit('credentials:saved', { email, action });
      return true;
    } catch (error) {
      console.error('Failed to save credentials:', error.message);
      return false;
    }
  }

  /**
   * Check if credentials file exists (for CLI init)
   */
  hasCredentialsFile() {
    const credentialsPath = path.resolve(this.config.credentialsFile);
    return fs.existsSync(credentialsPath);
  }

  /**
   * Process saved credentials (used by CLI init)
   */
  async processCredentials() {
    const credentialsPath = path.resolve(this.config.credentialsFile);

    if (!fs.existsSync(credentialsPath)) {
      return null;
    }

    try {
      const credentialsContent = fs.readFileSync(credentialsPath, 'utf8');
      const credentials = JSON.parse(credentialsContent);

      // Delete credentials file immediately for security
      fs.unlinkSync(credentialsPath);

      if (!this.flowNexusSDK) {
        throw new Error('Flow Nexus SDK not initialized');
      }

      // Authenticate using saved credentials
      if (credentials.action === 'register') {
        return await this.flowNexusSDK.register(
          credentials.email,
          credentials.password,
          'Agentic Marketing User'
        );
      } else {
        return await this.flowNexusSDK.login(credentials.email, credentials.password);
      }
    } catch (error) {
      console.error('Failed to process credentials:', error.message);
      throw error;
    }
  }

  /**
   * Interactive authentication prompt
   */
  async promptAuthentication() {
    if (!this.flowNexusSDK) {
      throw new Error('Flow Nexus SDK not initialized');
    }

    const inquirer = require('inquirer');

    console.log('\n🔐 Flow Nexus Authentication Required\n');

    const { action } = await inquirer.prompt([
      {
        type: 'list',
        name: 'action',
        message: 'Do you have a Flow Nexus account?',
        choices: [
          { name: 'Yes, I want to login', value: 'login' },
          { name: 'No, I need to register', value: 'register' },
          { name: 'Skip for now', value: 'skip' }
        ]
      }
    ]);

    if (action === 'skip') {
      return { success: false, skipped: true };
    }

    const { email, password } = await inquirer.prompt([
      {
        type: 'input',
        name: 'email',
        message: 'Enter your email:',
        validate: (input) => {
          const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
          return emailRegex.test(input) || 'Please enter a valid email';
        }
      },
      {
        type: 'password',
        name: 'password',
        message: 'Enter your password:',
        mask: '*'
      }
    ]);

    try {
      if (action === 'register') {
        return await this.flowNexusSDK.register(email, password, 'Agentic Marketing User');
      } else {
        return await this.flowNexusSDK.login(email, password);
      }
    } catch (error) {
      console.error('Authentication failed:', error.message);
      throw error;
    }
  }

  /**
   * Get current authentication status
   */
  getStatus() {
    return {
      authenticated: this.flowNexusSDK ? this.flowNexusSDK.isAuthenticated() : false,
      hasSession: !!this.sessionData,
      hasCredentialsFile: this.hasCredentialsFile(),
      user: this.sessionData ? this.sessionData.user : null
    };
  }

  /**
   * Check if authentication is required
   */
  requiresAuthentication() {
    return !this.flowNexusSDK || !this.flowNexusSDK.isAuthenticated();
  }
}

module.exports = AuthenticationManager;

#!/usr/bin/env node

/**
 * System Test Script for Agentic Marketing Platform
 * Tests with real Flow Nexus MCP tools and credentials
 */

const chalk = require('chalk');
const { main } = require('./main');

async function runSystemTests() {
  console.log(chalk.cyan('\n🧪 Starting Agentic Marketing System Tests\n'));

  // Set test credentials (non-interactive mode)
  process.env.FLOW_NEXUS_EMAIL = "ruv@ruv.net";
  process.env.FLOW_NEXUS_PASSWORD = "password123";
  process.env.FLOW_NEXUS_ACTION = "login";
  process.env.PORT = "3001"; // Use different port for testing
  process.env.DB_PATH = "./test-data/mediaspend-test.db";
  process.env.NODE_ENV = "test";

  console.log(chalk.yellow('📋 Test Configuration:'));
  console.log(chalk.gray(`   Email: ${process.env.FLOW_NEXUS_EMAIL}`));
  console.log(chalk.gray(`   Action: ${process.env.FLOW_NEXUS_ACTION}`));
  console.log(chalk.gray(`   Port: ${process.env.PORT}`));
  console.log(chalk.gray(`   Database: ${process.env.DB_PATH}`));

  try {
    // Prepare test environment
    console.log(chalk.yellow('\n🔧 Preparing test environment...'));
    const fs = require('fs');
    const path = require('path');

    // Create test data directory
    const testDataDir = './test-data';
    if (!fs.existsSync(testDataDir)) {
      fs.mkdirSync(testDataDir, { recursive: true });
    }

    // Start the server with real MCP tools
    console.log(chalk.cyan('\n🚀 Starting server with Flow Nexus MCP integration...\n'));

    const server = await main(); // This will use real MCP tools

    console.log(chalk.green('\n✅ Server started successfully!'));

    // Wait a moment for initialization
    await new Promise(resolve => setTimeout(resolve, 2000));

    // Run API tests
    await runAPITests();

    console.log(chalk.green('\n🎉 All tests completed successfully!'));

    // Cleanup
    console.log(chalk.yellow('\n🧹 Cleaning up...'));
    if (server && server.shutdown) {
      await server.shutdown();
    }

  } catch (error) {
    console.error(chalk.red('\n❌ Test failed:'), error.message);
    if (error.stack) {
      console.error(chalk.gray(error.stack));
    }
    process.exit(1);
  }
}

async function runAPITests() {
  console.log(chalk.cyan('\n🔍 Running API tests...'));

  const baseURL = `http://localhost:${process.env.PORT}`;

  try {
    // Test 1: Health check
    console.log(chalk.yellow('  Testing health endpoint...'));
    const healthResponse = await fetch(`${baseURL}/health`);
    const healthData = await healthResponse.json();

    console.log(chalk.gray(`    Status: ${healthData.status}`));
    console.log(chalk.gray(`    Database: ${healthData.database}`));
    console.log(chalk.gray(`    Flow Nexus: ${healthData.flowNexus}`));

    if (healthData.status === 'operational') {
      console.log(chalk.green('  ✅ Health check passed'));
    } else {
      throw new Error('Health check failed');
    }

    // Test 2: Flow Nexus status
    console.log(chalk.yellow('  Testing Flow Nexus status...'));
    const statusResponse = await fetch(`${baseURL}/api/flow-nexus/status`);
    const statusData = await statusResponse.json();

    console.log(chalk.gray(`    Authenticated: ${statusData.sdk?.authenticated}`));
    console.log(chalk.gray(`    Swarm Active: ${statusData.sdk?.swarm?.active}`));
    console.log(chalk.gray(`    Agent Count: ${statusData.sdk?.swarm?.agentCount}`));
    console.log(chalk.gray(`    Workflows: ${statusData.sdk?.workflows?.join(', ')}`));

    if (statusData.sdk?.authenticated) {
      console.log(chalk.green('  ✅ Flow Nexus authentication verified'));
    } else {
      console.log(chalk.yellow('  ⚠️  Flow Nexus not authenticated (expected in test mode)'));
    }

    // Test 3: Media planning endpoints
    console.log(chalk.yellow('  Testing media planning API...'));

    // Create test insertion order
    const ioResponse = await fetch(`${baseURL}/api/insertion-orders`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        campaign_name: 'Test Campaign',
        start_date: '2025-01-01',
        end_date: '2025-03-31',
        total_budget: 50000
      })
    });

    const ioData = await ioResponse.json();
    console.log(chalk.gray(`    Created IO: ${ioData.io_number}`));

    if (ioData.id) {
      console.log(chalk.green('  ✅ Insertion order creation passed'));
    } else {
      throw new Error('Insertion order creation failed');
    }

    // Test 4: Performance analytics
    console.log(chalk.yellow('  Testing analytics API...'));
    const analyticsResponse = await fetch(`${baseURL}/api/analytics/performance?start_date=2025-01-01&end_date=2025-01-31`);
    const analyticsData = await analyticsResponse.json();

    console.log(chalk.gray(`    Metrics period: ${analyticsData.period?.start_date} to ${analyticsData.period?.end_date}`));
    console.log(chalk.gray(`    Generated by: ${analyticsData.generated_by}`));

    if (analyticsData.metrics) {
      console.log(chalk.green('  ✅ Analytics API passed'));
    } else {
      throw new Error('Analytics API failed');
    }

    console.log(chalk.green('\n✅ All API tests passed!'));

  } catch (error) {
    console.error(chalk.red(`\n❌ API test failed: ${error.message}`));
    throw error;
  }
}

// Simple fetch implementation if not available
if (typeof fetch === 'undefined') {
  global.fetch = async (url, options = {}) => {
    const http = require('http');
    const https = require('https');
    const { URL } = require('url');

    const parsedUrl = new URL(url);
    const lib = parsedUrl.protocol === 'https:' ? https : http;

    return new Promise((resolve, reject) => {
      const req = lib.request({
        hostname: parsedUrl.hostname,
        port: parsedUrl.port,
        path: parsedUrl.pathname + parsedUrl.search,
        method: options.method || 'GET',
        headers: options.headers || {}
      }, (res) => {
        let data = '';
        res.on('data', chunk => data += chunk);
        res.on('end', () => {
          resolve({
            ok: res.statusCode >= 200 && res.statusCode < 300,
            status: res.statusCode,
            json: () => Promise.resolve(JSON.parse(data)),
            text: () => Promise.resolve(data)
          });
        });
      });

      req.on('error', reject);

      if (options.body) {
        req.write(options.body);
      }

      req.end();
    });
  };
}

// Run tests if called directly
if (require.main === module) {
  runSystemTests().catch(console.error);
}

module.exports = { runSystemTests };

